38	// ReadLatestSessionContent reads the latest session from an already-resolved
39	// committed reader and summary.
40	func ReadLatestSessionContent(ctx context.Context, reader SessionReader, checkpointID id.CheckpointID, summary *CheckpointSummary) (*SessionContent, error) {
41		if summary == nil || len(summary.Sessions) == 0 {
42			return nil, ErrCheckpointNotFound
43		}
44		latestIndex := len(summary.Sessions) - 1
45		content, err := reader.ReadSession(ctx, SessionIndexRef(checkpointID, latestIndex))
